def split_csv(line):
    fields = []
    i = 0
    n = len(line)

    while i <= n:
        # At the start of a field or at the end of the line
        if i == n:
            # End of line - we have one complete field
            fields.append('')
            break

        if line[i] == '"':
            # Quoted field
            i += 1
            field = []
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        # Doubled quote
                        field.append('"')
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check what follows: comma or end of line
                        if i == n:
                            fields.append(''.join(field))
                            break
                        elif line[i] == ',':
                            fields.append(''.join(field))
                            i += 1
                            if i == n:
                                # Trailing comma, add empty field
                                fields.append('')
                            break
                        else:
                            # Invalid: quote not followed by comma or end
                            return None
                else:
                    field.append(line[i])
                    i += 1
            else:
                # Loop ended without finding closing quote
                return None
        else:
            # Unquoted field
            field = []
            while i < n and line[i] != ',':
                if line[i] == '"':
                    # Double quote in unquoted field is invalid
                    return None
                field.append(line[i])
                i += 1

            fields.append(''.join(field))

            if i < n and line[i] == ',':
                i += 1
                if i == n:
                    # Trailing comma, add empty field
                    fields.append('')

    return fields

